import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Setting up the address book","description":"A company address book in the app – contacts from a Grid, with search, department filter and an offline copy.","frontmatter":{"title":"Setting up the address book","description":"A company address book in the app – contacts from a Grid, with search, department filter and an offline copy."},"headers":[],"relativePath":"en/apptiveteams/adressbuch.md","filePath":"en/apptiveteams/adressbuch.md","lastUpdated":1788846304000}'),r={name:"en/apptiveteams/adressbuch.md"};function s(i,t,n,c,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="setting-up-the-address-book" tabindex="-1">Setting up the address book <a class="header-anchor" href="#setting-up-the-address-book" aria-label="Permalink to &quot;Setting up the address book&quot;">​</a></h1><p>A tab of type <code>AddressBook</code> shows a company address book in the app: contacts with photo, phone, e-mail and address, a search and a filter by department. The contacts are rows in a Grid of your ApptiveGrid account. Optionally, companies appear as entries of their own, with a jump from a company to its people and back.</p><p>The app keeps an <strong>offline copy</strong> of the contacts per team on the device. The phone&#39;s own address book stays untouched; the app never asks for the contacts permission.</p><h2 id="the-tabs-row" tabindex="-1">The tabs row <a class="header-anchor" href="#the-tabs-row" aria-label="Permalink to &quot;The tabs row&quot;">​</a></h2><p>Add a row to the <code>tabs</code> Grid of the team Space:</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Value</th></tr></thead><tbody><tr><td><code>title</code></td><td>for example &quot;Contacts&quot;</td></tr><tr><td><code>icon</code></td><td>single-colour SVG</td></tr><tr><td><code>type</code></td><td><code>AddressBook</code></td></tr><tr><td><code>gridUri</code></td><td>link to the contacts Grid or a view on it</td></tr><tr><td><code>uri</code></td><td>alternatively: the link of a shared view</td></tr></tbody></table><p>You need <strong>one</strong> of the two fields. <code>gridUri</code> points at a Grid or view inside the team Space that members may see. If the contacts live in a Space your staff has no access to, share a view there via link and enter the link in <code>uri</code>. If both are set, <code>gridUri</code> wins. → <a href="/en/ansichten/ansicht-teilen">Sharing a view</a></p><h2 id="the-contacts-grid" tabindex="-1">The contacts Grid <a class="header-anchor" href="#the-contacts-grid" aria-label="Permalink to &quot;The contacts Grid&quot;">​</a></h2><p>Only <code>lastName</code> is required. Everything else appears when present; missing details are simply not shown. Field names are up to you, the <strong>Keys</strong> must match exactly. → <a href="/en/apptiveteams/team-space#keys-how-the-app-finds-its-grids">Assigning keys</a></p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>lastName</code></td><td>Text</td><td>yes</td><td>Last name</td></tr><tr><td><code>firstName</code></td><td>Text</td><td>no</td><td>First name</td></tr><tr><td><code>company</code></td><td>Text or Link</td><td>no</td><td>Company; as a link to a companies Grid, companies become entries of their own, see below</td></tr><tr><td><code>department</code></td><td>Text or Single Select</td><td>no</td><td>Department, team or site; the app filters by it</td></tr><tr><td><code>role</code></td><td>Text</td><td>no</td><td>Position or function</td></tr><tr><td><code>phone</code></td><td>Phone number</td><td>no</td><td>Landline or extension</td></tr><tr><td><code>mobile</code></td><td>Phone number</td><td>no</td><td>Mobile number</td></tr><tr><td><code>email</code></td><td>E-mail</td><td>no</td><td>E-mail address</td></tr><tr><td><code>photo</code></td><td>Files</td><td>no</td><td>Photo; the first image is used</td></tr><tr><td><code>address</code></td><td>Address or Text</td><td>no</td><td>Postal address</td></tr><tr><td><code>notes</code></td><td>Text</td><td>no</td><td>Notes, for example availability</td></tr><tr><td><code>active</code></td><td>Checkbox</td><td>no</td><td>Unchecked rows are hidden. Without the field, all rows are visible</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Hide former staff without deleting</p><p>Use <code>active</code> to hide contacts without deleting the row. A filtered view as the source serves the same purpose and additionally lets you hide columns from the app.</p></div><h2 id="optional-companies-as-entries-of-their-own" tabindex="-1">Optional: companies as entries of their own <a class="header-anchor" href="#optional-companies-as-entries-of-their-own" aria-label="Permalink to &quot;Optional: companies as entries of their own&quot;">​</a></h2><p>Turn <code>company</code> into a <strong>link</strong> to a second Grid and its rows appear in the address book as companies. From a company you jump to its people and from a person to their company. The companies Grid does not have to be registered anywhere; its address is part of the link.</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>Text</td><td>yes</td><td>Company name</td></tr><tr><td><code>phone</code></td><td>Phone number</td><td>no</td><td>Switchboard</td></tr><tr><td><code>email</code></td><td>E-mail</td><td>no</td><td>Central address</td></tr><tr><td><code>website</code></td><td>Weblink or Text</td><td>no</td><td>Website</td></tr><tr><td><code>address</code></td><td>Address or Text</td><td>no</td><td>Postal address</td></tr><tr><td><code>notes</code></td><td>Text</td><td>no</td><td>Notes</td></tr><tr><td><code>logo</code></td><td>Files</td><td>no</td><td>Logo; the first image is used</td></tr><tr><td><code>active</code></td><td>Checkbox</td><td>no</td><td>as for contacts</td></tr></tbody></table><p>If <code>company</code> stays a text field, there are no company entries; everything else works as before.</p><h2 id="how-the-app-works" tabindex="-1">How the app works <a class="header-anchor" href="#how-the-app-works" aria-label="Permalink to &quot;How the app works&quot;">​</a></h2><ul><li>When the tab is opened, the app loads the contacts and stores them as an offline copy per team. Without a connection it shows the last loaded state.</li><li>Search and department filter work on the copy, so offline too.</li><li>Signing out deletes the copies of all teams from the device.</li><li>If the required key <code>lastName</code> is missing, the tab shows a hint with the fields the Grid actually delivers instead of contacts.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/tabs">Setting up tabs</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>',19)])])}const b=e(r,[["render",s]]);export{m as __pageData,b as default};
